// Both exports take nothing and return nothing. The contract states a
// registered computation for `startTicker` only; `startTickerSilent` is the
// control, identical except that it states none.
//
// The signatures are `tsc`-clean on purpose: calling either anywhere is well
// typed, so whatever the checker reports here is nothing `tsc` reports.
export declare function startTicker(): void;
export declare function startTickerSilent(): void;
